use demostrike_rust_candidate::csdm::csdm_analysis as analysis;
use serde_json::{json,Value};
#[test] fn original_running_and_disconnect_pending_behavior(){
 let oracle:Value=serde_json::from_str(include_str!("fixtures/pg29-original-running-oracle.json")).unwrap();let make=|s:&str|json!({"checksum":s,"filePath":format!(r"C:\owned\{s}.dem"),"mapName":"de_nuke","source":"valve"});let mut q=analysis::Analyses::new();let mut events=vec![q.add(vec![make("a"),make("b")],Some("one"),None,||"<time>".into()).unwrap().unwrap()];let run=q.claim(1).unwrap();let a=q.set_running_status(run.run_id,"analyzing").unwrap();events.push(json!({"name":"analysis-status-changed","payload":a}));assert_eq!(json!(q.all()),oracle["snapshots"][0]["analyses"]);assert_eq!(json!(events),oracle["snapshots"][0]["events"]);assert!(q.claim(1).is_none());events.push(q.disconnect("one").unwrap());assert_eq!(json!(q.all()),oracle["snapshots"][1]["analyses"]);assert_eq!(json!(events),oracle["snapshots"][1]["events"]);
}


#[test] fn original_pending_ownership_event_payloads(){
 let oracle:Value=serde_json::from_str(include_str!("fixtures/pg25-original-analysis-oracle.json")).unwrap();let d=|s:&str|json!({"checksum":s,"filePath":format!(r"C:\owned\{s}.dem"),"mapName":"de_nuke","source":"valve"});let mut q=analysis::Analyses::new();let mut events=Vec::new();let mut steps=Vec::new();if let Some(e)=q.add(vec![d("a"),d("a")],Some("one"),None,||"<time>".into()).unwrap(){events.push(e)}steps.push(json!({"step":"duplicate-batch","analyses":q.all(),"events":events}));if let Some(e)=q.add(vec![d("a"),d("b")],Some("two"),Some(false),||"<time>".into()).unwrap(){events.push(e)}steps.push(json!({"step":"second-client","analyses":q.all(),"events":events}));if let Some(e)=q.disconnect("one"){events.push(e)}steps.push(json!({"step":"disconnect-one","analyses":q.all(),"events":events}));if let Some(e)=q.disconnect("two"){events.push(e)}steps.push(json!({"step":"disconnect-two","analyses":q.all(),"events":events}));q.clear();events.clear();if let Some(e)=q.add(vec![d("gui")],None,None,||"<time>".into()).unwrap(){events.push(e)}if let Some(e)=q.add(vec![d("gui")],Some("one"),None,||"<time>".into()).unwrap(){events.push(e)}if let Some(e)=q.disconnect("one"){events.push(e)}steps.push(json!({"step":"gui-untracked","analyses":q.all(),"events":events}));q.remove(&["gui"]);steps.push(json!({"step":"explicit-remove","analyses":q.all(),"events":events}));assert_eq!(json!(steps),oracle["snapshots"])
}
#[test] fn claims_obey_limit_and_finish_current(){let mut q=analysis::Analyses::new();let d=|s:&str|json!({"checksum":s,"filePath":"x","mapName":"n","source":"valve"});q.add(vec![d("a"),d("b")],Some("one"),None,||"t".into()).unwrap();assert!(q.claim(0).is_none());let a=q.claim(1).unwrap();assert!(q.claim(1).is_none());q.finish(a.run_id);let b=q.claim(1).unwrap();q.finish(b.run_id);assert!(q.all().is_empty());}
#[test] fn duplicate_running_items_need_independent_identity(){let mut q=analysis::Analyses::new();let demo=json!({"checksum":"same","filePath":"x","mapName":"n","source":"valve"});q.add(vec![demo.clone(),demo],None,None,||"t".into()).unwrap();let first=q.claim(2).unwrap();let second=q.claim(2).unwrap();assert_ne!(first.run_id,second.run_id);q.set_running_status(second.run_id,"analyzing").unwrap();assert_eq!(q.all()[0]["status"],"pending");assert_eq!(q.all()[1]["status"],"analyzing");q.finish(first.run_id);assert!(q.all().is_empty());assert!(q.set_running_status(second.run_id,"analyze-success").is_some(),"detached running task still emits updates");}



#[test] fn detached_duplicate_stdout_matches_original(){let o:Value=serde_json::from_str(include_str!("fixtures/pg29-original-duplicate-oracle.json")).unwrap();let demo=json!({"checksum":"a","filePath":r"C:\owned\a.dem","mapName":"de_nuke","source":"valve"});let mut q=analysis::Analyses::new();q.add(vec![demo.clone(),demo],Some("one"),None,||"<time>".into()).unwrap();let a=q.claim(2).unwrap();let b=q.claim(2).unwrap();q.set_running_status(a.run_id,"analyzing");q.set_running_status(b.run_id,"analyzing");q.finish(a.run_id);assert_eq!(json!(q.all()),o["snapshots"][1]["analyses"]);let update=q.append_output(b.run_id,"late").unwrap();let actual=json!({"name":"analysis-status-changed","payload":update});let events=o["snapshots"][2]["events"].as_array().unwrap();assert_eq!(actual,*events.last().unwrap());}

#[test] fn error_code_status_matches_original_transition(){let oracle:Value=serde_json::from_str(include_str!("fixtures/pg25-analysis-lifecycle-oracle.json")).unwrap();let error=oracle["scenarios"][3]["events"].as_array().unwrap().last().unwrap()["payload"]["errorCode"].as_i64().unwrap();let demo=json!({"checksum":"a","filePath":"x","mapName":"n","source":"valve"});let mut q=analysis::Analyses::new();q.add(vec![demo],None,None,||"t".into()).unwrap();let id=q.claim(1).unwrap().run_id;let item=q.set_status_with_error(id,"insert-error",Some(error)).unwrap();assert_eq!(item["errorCode"],error);let item=q.set_status_with_error(id,"analyzing",None).unwrap();assert!(item.get("errorCode").is_none());}

#[test] fn added_times_are_captured_for_each_original_analysis(){let d=|s:&str|json!({"checksum":s,"filePath":"x","mapName":"n","source":"valve"});let mut q=analysis::Analyses::new();let mut n=0;let event=q.add(vec![d("a"),d("b")],None,None,||{n+=1;format!("time{n}")}).unwrap().unwrap();assert_eq!(n,2);assert_eq!(event["payload"][0]["addedAt"],"time1");assert_eq!(event["payload"][1]["addedAt"],"time2");}
